arguments.argument:
if view_wview<mouse_x-view_xview{view_xview=min(room_width-view_wview,view_xview+global.mouse_speed)}
if view_hview<mouse_y-view_yview{view_yview=min(room_height-view_hview,view_yview+global.mouse_speed)}
if 0>mouse_x-view_xview{view_xview=max(0,view_xview-global.mouse_speed)}
if 0>mouse_y-view_yview{view_yview=max(0,view_yview-global.mouse_speed)}
//마우스로 뷰 이동

if global.mouse_ropes=1 and sys_minimap.ok=0
{
if view_wview<mouse_x-view_xview{window_views_mouse_set(view_xview+view_wview-2,mouse_y)}
if 0>mouse_x-view_xview{window_views_mouse_set(view_xview+2,mouse_y)}
if view_hview<mouse_y-view_yview{window_views_mouse_set(mouse_x,view_yview+view_hview-2)}
if 0>mouse_y-view_yview{window_views_mouse_set(mouse_x,view_yview+2)}
}
//마우스 좌표이동

x=mouse_x
y=mouse_y

if x>room_width{x=room_width-2}
if x<0{x=2}

if y>room_height{y=room_height-2}
if y<0{y=2}

//좌표 이동
